// ПОДГОТОВКА (тест не выдаёт — разрешение на гранты было разовым на раунд 10): админка → משתמשים → «בדיקה כללי» (new10) → «הענקת מתנה».
// Без гранта тест падает с подсказкой «ОКРУЖЕНИЕ». Тест тратит грант new10.
// УБОРКА: подарок и сообщения удалить нельзя — остаются в чатах new10↔new02 (77cad0cb) и user4↔new02 (аннотация cleanup).
// В конце new02 отвечает new10 — снимает запрет «до ответа» для следующих прогонов.
// Не проверен на живой странице (порядок строк /matches, метка «מתנה») — проверить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { N2, N10, U4, phone, openChat, openSendScreen, giftMessageField, freeSendButton, awaitingReplyHint } from './gifts-helpers';

// Позиция строки собеседника в /matches (верх строки, px). Строка — кнопка, имя в начале.
async function rowTop(page: Page, name: string): Promise<number> {
  const row = page.getByRole('button', { name: new RegExp(`^${name}`) }).first();
  await expect(row).toBeVisible({ timeout: 15_000 });
  const box = await row.boundingBox();
  if (!box) throw new Error(`нет строки «${name}» в /matches`);
  return box.y;
}

async function sendText(page: Page, text: string) {
  await page.getByRole('textbox', { name: 'כתוב הודעה' }).fill(text);
  const w = page.waitForResponse((x) => x.url().includes('/rest/v1/messages') && x.request().method() === 'POST');
  await page.getByRole('button', { name: 'שליחה' }).click();
  expect((await w).ok(), `сообщение «${text}» отправлено`).toBeTruthy();
}

test.describe('Подарки: грант, приоритет в списке получателя', () => {
  test.describe.configure({ mode: 'serial', timeout: 300_000 });

  test('Бесплатный подарок new10→new02: грант списан (больше нет «חינם»), у new02 чат с подарком выше более нового сообщения user4, метка «מתנה», без цены; после открытия метка уходит, порядок по времени @iphone @data (#802740 #64bad0 #ae03b1 #f676fe)', async ({ asUser }) => {
    const s = await asUser('new10');
    const u4 = await asUser('user4');
    const r = await asUser('new02');
    const t = Date.now();
    const msg = `QA-AUTO prio ${t}`;
    const plain = `QA-AUTO plain ${t}`;
    let sent = false;
    let replied = false;
    try {
      for (const p of [s, u4, r]) await phone(p);

      // 1. new10: 🎁 → «ורד זהב» → «שליחת מתנה • חינם».
      await openChat(s, N2);
      await openSendScreen(s, N2);
      await expect(awaitingReplyHint(s, N2), 'ОКРУЖЕНИЕ: прошлый подарок new10→new02 без ответа — ответь вручную new02 → чат «בדיקה כללי»').toHaveCount(0);
      const btn = freeSendButton(s);
      await expect(btn, 'ОКРУЖЕНИЕ: нет бесплатного подарка у new10 — выдай грант: админка → משתמשים → «בדיקה כללי» → «הענקת מתנה»').toBeEnabled({ timeout: 15_000 });
      await giftMessageField(s).fill(msg);
      const wait = s.waitForResponse((x) => x.url().includes('/rpc/send_gift') && x.request().method() === 'POST');
      await btn.click();
      const res = await wait;
      expect(res.ok(), `send_gift: ${res.status()} ${await res.text()}`).toBeTruthy();
      sent = true;
      await expect(s.getByText('המתנה נשלחה').first()).toBeVisible();

      // 2. new10: грант списан — «חינם» больше нет (#802740 AC 4–5).
      await openChat(s, N2);
      await s.getByRole('button', { name: /מתנה|🎁|gift/i }).first().click();
      await expect(s.getByText('ורד זהב').first()).toBeVisible({ timeout: 20_000 });
      await expect(freeSendButton(s)).toHaveCount(0);
      await expect(s.getByText(/^חינם$/)).toHaveCount(0);

      // 3. user4 пишет new02 обычное сообщение — оно новее подарка.
      await openChat(u4, N2);
      await sendText(u4, plain);

      // 4. new02: чат с подарком выше, метка «מתנה», без цены (#ae03b1 AC 1–3, 5; #f676fe; #802740 AC 6).
      await expect(async () => {
        await r.goto('/matches');
        const giftRow = r.getByRole('button', { name: new RegExp(`^${N10}`) }).first();
        await expect(giftRow).toContainText(/לך מתנה|מתנה/, { timeout: 10_000 });
        await expect(r.getByRole('button', { name: new RegExp(`^${U4}`) }).first()).toContainText(plain, { timeout: 10_000 });
        expect(await rowTop(r, N10), 'подарок выше более нового сообщения').toBeLessThan(await rowTop(r, U4));
      }).toPass({ timeout: 90_000 });
      await expect(r.getByRole('button', { name: new RegExp(`^${N10}`) }).first()).not.toContainText(/₪|חינם/);

      // 5. new02 открывает чат с подарком → карточка без цены; назад → метка ушла, порядок по времени (#ae03b1 AC 4).
      await openChat(r, N10);
      await expect(r.getByText(msg).last()).toBeVisible({ timeout: 30_000 });
      await expect(r.getByText(/₪/)).toHaveCount(0);
      await expect(async () => {
        await r.goto('/matches');
        await expect(r.getByRole('button', { name: new RegExp(`^${N10}`) }).first()).not.toContainText(/לך מתנה/, { timeout: 10_000 });
        expect(await rowTop(r, U4), 'после открытия — порядок по времени').toBeLessThan(await rowTop(r, N10));
      }).toPass({ timeout: 60_000 });

      // 6. new02 отвечает new10 — снимает запрет «до ответа».
      await openChat(r, N10);
      await sendText(r, `${msg} reply`);
      replied = true;
    } finally {
      if (sent) test.info().annotations.push({ type: 'cleanup', description: `подарок new10→new02 «${msg}»${replied ? ' + ответ new02' : ''}, сообщение user4→new02 «${plain}» — удалить нельзя (в список чистки); грант new10 потрачен` });
      if (sent && !replied) test.info().annotations.push({ type: 'cleanup', description: 'new02 НЕ ответил new10 — ответь вручную (new02 → чат «בדיקה כללי»), иначе следующий прогон упрётся в awaiting_reply' });
      await saveSession(s, 'new10');
      await saveSession(u4, 'user4');
      await saveSession(r, 'new02');
    }
  });
});
